        function B = convertbvecs2twixBs(bvals,bvecs)
            % MATLAB implementation of how B-matrix is stored in twix header
            % based on original source code
            nv = size(bvecs,2);

            if isscalar(bvals)
                bvals = repmat(bvals,nv,1);
            end

            B = zeros(3,3,nv,'uint16');
            for n=1:nv
                Bloc = bvals(n)*bvecs(:,n)*bvecs(:,n)';
                Bloc([1;5;9]) = Bloc([1;5;9]).*sign(bvecs(:,n));

                % first convert to long, then interpret the lowest bits as short
                tc = typecast(int32(Bloc(:)+16384.5),"uint16"); % typecase requires a vector
                B(:,:,n) = reshape(tc(1:2:end),3,3); % throw away the highest bits
            end
        end

        function bvecs = converttwixBstobvecs(B)
            % implementation of retrieving b-vectors from B-matrix in twix header
            % may not be exactly accurate, as I have not seen the original code
            % which does this
            nv = size(B,3);
            bvecs = zeros(3,nv);
            for n=1:nv
                Bloc = double(B(:,:,n))-16385;
                s = sign(Bloc([1;5;9])); % diagonal elements of 3x3 matrix
                Bloc([1;5;9]) = abs(diag(Bloc));
                [v,e] = eig(Bloc);
                [~,f] = max(abs(diag(e)));
                vec = v(:,f);
                bvecs(:,n) = vec*sign(vec'*(s.*abs(vec)));
            end
        end

        % rotation around z in 3D
        function R = rotzd(alpha)
            R = [cosd(alpha), -sind(alpha), 0;
                sind(alpha), cosd(alpha), 0;
                0, 0, 1];
        end

        % rotation around y in 3D
        function R = rotyd(beta)
            R = [cosd(beta), 0, sind(beta);
                0, 1, 0;
                -sind(beta), 0, cosd(beta)];
        end

        % arbitrary rotation in 3D specified by zyz Euler angles
        function R = rotzyzd(alpha,beta,gamma)
            R = testutils.rotzd(gamma)*testutils.rotyd(beta)*testutils.rotzd(alpha);
        end

    end
